CREATE FUNCTION public.buddy_matches(_season_id uuid,_language boolean DEFAULT false,_timezone boolean DEFAULT false,_goals boolean DEFAULT false,_gender boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE uid uuid:=auth.uid(); me record;p record;rel record;shared jsonb;card jsonb;incoming jsonb:='[]';results jsonb:='[]';buddy jsonb:=NULL;score integer;offset_h numeric;own_days integer;active_days integer;
BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;SELECT * INTO me FROM profiles WHERE id=uid;
SELECT count(*) INTO own_days FROM daily_scores WHERE user_id=uid AND season_id=_season_id AND completion>=0.6;
FOR p IN SELECT * FROM profiles WHERE id<>uid AND EXISTS(SELECT 1 FROM season_entries WHERE user_id=profiles.id AND season_id=_season_id) ORDER BY id LOOP
IF EXISTS(SELECT 1 FROM buddy_requests WHERE status='blocked' AND uid IN(from_user,to_user) AND p.id IN(from_user,to_user)) THEN CONTINUE;END IF;
SELECT * INTO rel FROM buddy_requests WHERE uid IN(from_user,to_user) AND p.id IN(from_user,to_user) AND status IN('pending','accepted') ORDER BY status LIMIT 1;
IF rel.id IS NULL AND (NOT p.show_on_public_board OR p.birth_date IS NULL OR p.birth_date>current_date-interval '18 years' OR me.birth_date IS NULL OR me.birth_date>current_date-interval '18 years' OR EXISTS(SELECT 1 FROM buddy_requests WHERE status='accepted' AND p.id IN(from_user,to_user))) THEN CONTINUE;END IF;
SELECT coalesce(jsonb_agg(jsonb_build_object('key',ht.key,'name',ht.name,'color',ht.color,'icon',ht.icon)),'[]') INTO shared FROM user_habits h JOIN habit_templates ht ON ht.id=h.template_id WHERE h.user_id=p.id AND h.season_id=_season_id AND h.active AND (NOT ht.is_faith OR p.faith_public) AND EXISTS(SELECT 1 FROM user_habits mine WHERE mine.user_id=uid AND mine.season_id=_season_id AND mine.template_id=h.template_id AND mine.active);
offset_h:=extract(epoch FROM((now() AT TIME ZONE p.timezone)-(now() AT TIME ZONE me.timezone)))/3600;
SELECT count(*) INTO active_days FROM daily_scores WHERE user_id=p.id AND season_id=_season_id AND completion>=0.6;
score:=25+CASE WHEN p.language=me.language THEN 20 ELSE 0 END+CASE WHEN abs(offset_h)<=2 THEN 20 ELSE 0 END+least(25,jsonb_array_length(shared)*10)+CASE WHEN abs(active_days-own_days)<=7 THEN 10 ELSE 0 END;
card:=jsonb_build_object('user_id',p.id,'display_name',p.display_name,'handle',p.handle,'avatar_url',p.avatar_url,'country_code',p.country_code,'city',p.city,'utc_offset',extract(epoch FROM((now() AT TIME ZONE p.timezone)-(now() AT TIME ZONE 'UTC')))/3600,'streak',coalesce((SELECT streak FROM daily_scores WHERE user_id=p.id AND season_id=_season_id ORDER BY day DESC LIMIT 1),0),'active_days',active_days,'shared',shared,'match',score,'status',rel.status,'crew_id',rel.crew_id);
IF rel.status='accepted' THEN buddy:=card;ELSIF rel.status='pending' AND rel.to_user=uid THEN incoming:=incoming||jsonb_build_array(card);
ELSIF rel.id IS NULL AND (NOT _language OR p.language=me.language) AND (NOT _timezone OR abs(offset_h)<=2) AND (NOT _goals OR jsonb_array_length(shared)>0) AND (NOT _gender OR p.gender IS NOT NULL AND me.gender IS NOT NULL AND p.gender=me.gender) THEN results:=results||jsonb_build_array(card);END IF;
END LOOP;
SELECT coalesce(jsonb_agg(value),'[]') INTO results FROM(SELECT value FROM jsonb_array_elements(results) ORDER BY (value->>'match')::integer DESC LIMIT 30)x;
RETURN jsonb_build_object('eligible',coalesce(me.birth_date<=current_date-interval '18 years',false),'buddy',buddy,'incoming',incoming,'results',results);
END $$;
CREATE OR REPLACE FUNCTION public.buddy_directory(_season_id uuid,_search text DEFAULT '') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.buddy_matches(_season_id); $$;
CREATE FUNCTION public.detox_overview() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE uid uuid:=auth.uid();d date;wk date;duel record;base integer;saved integer;days integer;
BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'not_authenticated';END IF;d:=public._local_today(uid);wk:=date_trunc('week',d)::date;
SELECT * INTO duel FROM detox_duels WHERE uid IN(a,b) AND status IN('pending','active','finished') ORDER BY week_start DESC LIMIT 1;
IF duel.id IS NOT NULL THEN UPDATE detox_duels SET a_avg_min=(SELECT round(avg(social_minutes),1) FROM screen_time_logs WHERE user_id=duel.a AND day BETWEEN duel.week_start AND least(d,duel.week_start+6)),b_avg_min=(SELECT round(avg(social_minutes),1) FROM screen_time_logs WHERE user_id=duel.b AND day BETWEEN duel.week_start AND least(d,duel.week_start+6)),status=CASE WHEN status='active' AND d>duel.week_start+6 THEN 'finished' ELSE status END WHERE id=duel.id RETURNING * INTO duel;END IF;
SELECT social_minutes INTO base FROM screen_time_logs WHERE user_id=uid ORDER BY day LIMIT 1;
SELECT count(*),greatest(0,coalesce(sum(base-social_minutes),0)) INTO days,saved FROM screen_time_logs WHERE user_id=uid AND day BETWEEN wk AND d;
RETURN jsonb_build_object('today_minutes',(SELECT social_minutes FROM screen_time_logs WHERE user_id=uid AND day=d),'baseline',base,'saved_minutes',saved,'logged_days',days,'days_left',greatest(0,wk+7-d),'duel',CASE WHEN duel.id IS NULL THEN NULL ELSE to_jsonb(duel)||jsonb_build_object('opponent_name',(SELECT display_name FROM profiles WHERE id=CASE WHEN duel.a=uid THEN duel.b ELSE duel.a END),'mine',CASE WHEN duel.a=uid THEN duel.a_avg_min ELSE duel.b_avg_min END,'theirs',CASE WHEN duel.a=uid THEN duel.b_avg_min ELSE duel.a_avg_min END,'mine_days',(SELECT count(*) FROM screen_time_logs WHERE user_id=uid AND day BETWEEN duel.week_start AND least(d,duel.week_start+6)),'their_days',(SELECT count(*) FROM screen_time_logs WHERE user_id=CASE WHEN duel.a=uid THEN duel.b ELSE duel.a END AND day BETWEEN duel.week_start AND least(d,duel.week_start+6))) END,'targets',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'name',p.display_name)) FROM profiles p WHERE p.id<>uid AND NOT EXISTS(SELECT 1 FROM buddy_requests b WHERE b.status='blocked' AND uid IN(b.from_user,b.to_user) AND p.id IN(b.from_user,b.to_user)) AND(EXISTS(SELECT 1 FROM buddy_requests r WHERE r.status='accepted' AND uid IN(r.from_user,r.to_user) AND p.id IN(r.from_user,r.to_user)) OR EXISTS(SELECT 1 FROM crew_members a JOIN crew_members b USING(crew_id) WHERE a.user_id=uid AND b.user_id=p.id))),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.buddy_matches(uuid,boolean,boolean,boolean,boolean),public.detox_overview() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.buddy_matches(uuid,boolean,boolean,boolean,boolean),public.detox_overview() TO authenticated;